scwin.onpageunload = function() {};
scwin.footerExp = function(value) {
    if (value > 100000) {
        grdExp2.setFooterStyle("column36", "color", "red");
    } else {
        grdExp2.setFooterStyle("column36", "color", "blue");
    }
    return value;
}

scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).innerText == value) {
        return true;
    }
    return false
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_grdExp2__col5', 'key-sequence', {
        sequence: "34568"
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_grdExp2__col5', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grdExp2_cell_0_5')");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#G_grdExp2__col5').val('')");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grdExp2_column36').innerText == '272,826'", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
